package com.tekwatt.ocpp.websocket;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import com.tekwatt.ocpp.service.*;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Component;import org.springframework.web.socket.*;import org.springframework.web.socket.handler.TextWebSocketHandler;
@Component public class OcppWebSocketHandler extends TextWebSocketHandler implements SubProtocolCapable{private final ObjectMapper json;private final ConnectionRegistry registry;private final OcppAuditService audit;public OcppWebSocketHandler(ObjectMapper j,ConnectionRegistry r,OcppAuditService a){json=j;registry=r;audit=a;}public List<String>getSubProtocols(){return List.of("ocpp2.0.1","ocpp1.6");}public void afterConnectionEstablished(WebSocketSession s){registry.add(station(s),s);}protected void handleTextMessage(WebSocketSession s,TextMessage message)throws Exception{String station=station(s);try{JsonNode root=json.readTree(message.getPayload());if(!root.isArray()||root.size()<3||root.get(0).asInt()!=2){error(s,station,root.size()>1?root.get(1).asText():"unknown","FormationViolation","Expected OCPP CALL array");return;}String uid=root.get(1).asText(),action=root.get(2).asText();audit.record(station,"IN",2,uid,action,message.getPayload());ObjectNode response=handle(s.getAcceptedProtocol(),action);ArrayNode frame=json.createArrayNode().add(3).add(uid).add(response);send(s,station,3,uid,action,frame);}catch(Exception e){error(s,station,"unknown","InternalError",e.getMessage());}}private ObjectNode handle(String protocol,String action){boolean v201="ocpp2.0.1".equals(protocol);ObjectNode r=json.createObjectNode();switch(action){case"BootNotification"->r.put("status","Accepted").put("currentTime",Instant.now().toString()).put("interval",60);case"Heartbeat"->r.put("currentTime",Instant.now().toString());case"Authorize"->{String field=v201?"idTokenInfo":"idTagInfo";r.set(field,json.valueToTree(Map.of("status","Accepted")));}case"StartTransaction"->{if(v201)throw new IllegalArgumentException("Use TransactionEvent with OCPP 2.0.1");r.put("transactionId",Math.abs(UUID.randomUUID().hashCode())).set("idTagInfo",json.valueToTree(Map.of("status","Accepted")));}case"TransactionEvent"->{if(!v201)throw new IllegalArgumentException("TransactionEvent requires OCPP 2.0.1");}case"StatusNotification","StopTransaction","MeterValues","NotifyEvent"->{}default->throw new IllegalArgumentException("Unsupported action: "+action);}return r;}private void send(WebSocketSession s,String station,int type,String uid,String action,JsonNode frame)throws Exception{String text=json.writeValueAsString(frame);s.sendMessage(new TextMessage(text));audit.record(station,"OUT",type,uid,action,text);}private void error(WebSocketSession s,String station,String uid,String code,String description)throws Exception{ArrayNode f=json.createArrayNode();f.add(4).add(uid).add(code).add(description==null?"":description).addObject();send(s,station,4,uid,null,f);}public void afterConnectionClosed(WebSocketSession s,CloseStatus status){registry.remove(station(s),s);}private String station(WebSocketSession s){return (String)s.getAttributes().get("stationId");}}
